-- READ-ONLY aggregate; exact-key source rows absent from reconstruction. UTC fixed bounds.
WITH c AS (SELECT CASE WHEN o.dateTime < 1293840000 THEN 2010 ELSE 2011 END AS utc_year, o.usUnits AS ou, w.usUnits AS wu, o.interval AS oi, w.interval AS wi, o.`ET` AS old_ET, w.`ET` AS wh_ET, o.`UV` AS old_UV, w.`UV` AS wh_UV, o.`altimeter` AS old_altimeter, w.`altimeter` AS wh_altimeter, o.`barometer` AS old_barometer, w.`barometer` AS wh_barometer, o.`consBatteryVoltage` AS old_consBatteryVoltage, w.`consBatteryVoltage` AS wh_consBatteryVoltage, o.`dewpoint` AS old_dewpoint, w.`dewpoint` AS wh_dewpoint, o.`extraHumid1` AS old_extraHumid1, w.`extraHumid1` AS wh_extraHumid1, o.`extraHumid2` AS old_extraHumid2, w.`extraHumid2` AS wh_extraHumid2, o.`extraTemp1` AS old_extraTemp1, w.`extraTemp1` AS wh_extraTemp1, o.`extraTemp2` AS old_extraTemp2, w.`extraTemp2` AS wh_extraTemp2
FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime
WHERE o.dateTime >= 1262304000 AND o.dateTime < 1325376000 AND r.dateTime IS NULL)
SELECT utc_year, 'ET' AS field_name, COUNT(*) AS source_only_rows, SUM(old_ET IS NOT NULL) AS old_nonnull, SUM(wh_ET IS NOT NULL) AS wh_nonnull, SUM(old_ET IS NOT NULL AND wh_ET IS NOT NULL AND old_ET <=> wh_ET) AS paired_equal, SUM(old_ET IS NOT NULL AND wh_ET IS NOT NULL AND NOT(old_ET <=> wh_ET)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'UV' AS field_name, COUNT(*) AS source_only_rows, SUM(old_UV IS NOT NULL) AS old_nonnull, SUM(wh_UV IS NOT NULL) AS wh_nonnull, SUM(old_UV IS NOT NULL AND wh_UV IS NOT NULL AND old_UV <=> wh_UV) AS paired_equal, SUM(old_UV IS NOT NULL AND wh_UV IS NOT NULL AND NOT(old_UV <=> wh_UV)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'altimeter' AS field_name, COUNT(*) AS source_only_rows, SUM(old_altimeter IS NOT NULL) AS old_nonnull, SUM(wh_altimeter IS NOT NULL) AS wh_nonnull, SUM(old_altimeter IS NOT NULL AND wh_altimeter IS NOT NULL AND old_altimeter <=> wh_altimeter) AS paired_equal, SUM(old_altimeter IS NOT NULL AND wh_altimeter IS NOT NULL AND NOT(old_altimeter <=> wh_altimeter)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'barometer' AS field_name, COUNT(*) AS source_only_rows, SUM(old_barometer IS NOT NULL) AS old_nonnull, SUM(wh_barometer IS NOT NULL) AS wh_nonnull, SUM(old_barometer IS NOT NULL AND wh_barometer IS NOT NULL AND old_barometer <=> wh_barometer) AS paired_equal, SUM(old_barometer IS NOT NULL AND wh_barometer IS NOT NULL AND NOT(old_barometer <=> wh_barometer)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'consBatteryVoltage' AS field_name, COUNT(*) AS source_only_rows, SUM(old_consBatteryVoltage IS NOT NULL) AS old_nonnull, SUM(wh_consBatteryVoltage IS NOT NULL) AS wh_nonnull, SUM(old_consBatteryVoltage IS NOT NULL AND wh_consBatteryVoltage IS NOT NULL AND old_consBatteryVoltage <=> wh_consBatteryVoltage) AS paired_equal, SUM(old_consBatteryVoltage IS NOT NULL AND wh_consBatteryVoltage IS NOT NULL AND NOT(old_consBatteryVoltage <=> wh_consBatteryVoltage)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'dewpoint' AS field_name, COUNT(*) AS source_only_rows, SUM(old_dewpoint IS NOT NULL) AS old_nonnull, SUM(wh_dewpoint IS NOT NULL) AS wh_nonnull, SUM(old_dewpoint IS NOT NULL AND wh_dewpoint IS NOT NULL AND old_dewpoint <=> wh_dewpoint) AS paired_equal, SUM(old_dewpoint IS NOT NULL AND wh_dewpoint IS NOT NULL AND NOT(old_dewpoint <=> wh_dewpoint)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'extraHumid1' AS field_name, COUNT(*) AS source_only_rows, SUM(old_extraHumid1 IS NOT NULL) AS old_nonnull, SUM(wh_extraHumid1 IS NOT NULL) AS wh_nonnull, SUM(old_extraHumid1 IS NOT NULL AND wh_extraHumid1 IS NOT NULL AND old_extraHumid1 <=> wh_extraHumid1) AS paired_equal, SUM(old_extraHumid1 IS NOT NULL AND wh_extraHumid1 IS NOT NULL AND NOT(old_extraHumid1 <=> wh_extraHumid1)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'extraHumid2' AS field_name, COUNT(*) AS source_only_rows, SUM(old_extraHumid2 IS NOT NULL) AS old_nonnull, SUM(wh_extraHumid2 IS NOT NULL) AS wh_nonnull, SUM(old_extraHumid2 IS NOT NULL AND wh_extraHumid2 IS NOT NULL AND old_extraHumid2 <=> wh_extraHumid2) AS paired_equal, SUM(old_extraHumid2 IS NOT NULL AND wh_extraHumid2 IS NOT NULL AND NOT(old_extraHumid2 <=> wh_extraHumid2)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'extraTemp1' AS field_name, COUNT(*) AS source_only_rows, SUM(old_extraTemp1 IS NOT NULL) AS old_nonnull, SUM(wh_extraTemp1 IS NOT NULL) AS wh_nonnull, SUM(old_extraTemp1 IS NOT NULL AND wh_extraTemp1 IS NOT NULL AND old_extraTemp1 <=> wh_extraTemp1) AS paired_equal, SUM(old_extraTemp1 IS NOT NULL AND wh_extraTemp1 IS NOT NULL AND NOT(old_extraTemp1 <=> wh_extraTemp1)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'extraTemp2' AS field_name, COUNT(*) AS source_only_rows, SUM(old_extraTemp2 IS NOT NULL) AS old_nonnull, SUM(wh_extraTemp2 IS NOT NULL) AS wh_nonnull, SUM(old_extraTemp2 IS NOT NULL AND wh_extraTemp2 IS NOT NULL AND old_extraTemp2 <=> wh_extraTemp2) AS paired_equal, SUM(old_extraTemp2 IS NOT NULL AND wh_extraTemp2 IS NOT NULL AND NOT(old_extraTemp2 <=> wh_extraTemp2)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year
ORDER BY utc_year, field_name;
